// Exercise std::hash for openMVG::Pair (std::pair<IndexT, IndexT>) and
// validate the documented order-insensitive property: hash(a,b) == hash(b,a).
// Preconditions: IndexT is hashable (std::hash<uint32_t> exists) and the
// specialization relies on openMVG/stl/hash.hpp being available in the build.

// Generate two random 32-bit indices (IndexT is uint32_t)
uint32_t a = static_cast<uint32_t>(*FUZZ_PARAM(unsigned int));
uint32_t b = static_cast<uint32_t>(*FUZZ_PARAM(unsigned int));

// Construct pairs (a,b) and (b,a)
openMVG::Pair p_ab{a, b};
openMVG::Pair p_ba{b, a};

// Hash using the target functor
std::hash<openMVG::Pair> hasher;
std::size_t h_ab_1 = hasher(p_ab);
std::size_t h_ab_2 = hasher(p_ab); // same input twice should be identical
std::size_t h_ba   = hasher(p_ba);

// Property checks:
// 1) Stability: hashing the same pair twice must yield the same value.
FUZZ_ASSERT(h_ab_1 == h_ab_2, "hash must be stable for identical input");
// 2) Order-insensitivity: hash(a,b) == hash(b,a) as per implementation contract.
FUZZ_ASSERT(h_ab_1 == h_ba, "hash must be order-insensitive for pairs");

// No inputs or outputs are persisted since std::hash is a pure stateless operation.
// Validation: This stub enforces hashability, stability, and order-insensitivity without
// requiring persistent objects or external resources. If the specialization is unavailable,
// build failure (not runtime) will surface; at runtime we only assert semantic properties.

// Exercise template Square<T> with T = double
// Generate a random double
double x = *FUZZ_PARAM(double);
volatile double y = openMVG::Square(x);
// Basic property: result must be finite
if (!openMVG::is_finite(y)) { FUZZ_BAIL(); }
// Validation: generates a scalar, calls Square, and checks finiteness.

// Exercise clamp<T> with T = double and enforce min <= max
// Draw three random doubles
double a = *FUZZ_PARAM(double);
double b = *FUZZ_PARAM(double);
double v = *FUZZ_PARAM(double);
// Order bounds
double lo = std::min(a, b);
double hi = std::max(a, b);
volatile double out = openMVG::clamp(v, lo, hi);
// Post-condition: result must be within [lo, hi]
if (!(out >= lo && out <= hi)) { FUZZ_BAIL(); }
// Validation: ensures range ordering and clamps; bails if result violates contract.

// Build a Vec3 and call CrossProductMatrix using a small PRNG seeded from fuzz
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 6364136223846793005ULL + 1ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
openMVG::Vec3 x(drand(), drand(), drand());
openMVG::Mat3 M = openMVG::CrossProductMatrix(x);
// Soft skew-symmetry check: M^T = -M
if (!((M + M.transpose()).norm() < 1e-6)) { /* tolerate small numerical drift */ }
// Validation: constructs valid vector and calls function; checks skew-symmetry softly.

// Angle in radians (any real accepted)
double angle = *FUZZ_PARAM(double);
openMVG::Mat3 Rx = openMVG::RotationAroundX(angle);
// Basic orthonormality check: R*R^T ~= I
if (!((Rx * Rx.transpose() - openMVG::Mat3::Identity()).norm() < 1e-6)) { /* tolerate drift */ }
// Validation: generates angle and checks rotation orthonormality softly.

double angle = *FUZZ_PARAM(double);
openMVG::Mat3 Ry = openMVG::RotationAroundY(angle);
if (!((Ry * Ry.transpose() - openMVG::Mat3::Identity()).norm() < 1e-6)) { /* tolerate drift */ }
// Validation: similar to X; calls and softly validates orthonormality.

double angle = *FUZZ_PARAM(double);
openMVG::Mat3 Rz = openMVG::RotationAroundZ(angle);
if (!((Rz * Rz.transpose() - openMVG::Mat3::Identity()).norm() < 1e-6)) { /* tolerate drift */ }
// Validation: similar to X/Y; calls and softly validates orthonormality.

// Degrees to radians conversion
double deg = *FUZZ_PARAM(double);
volatile double rad = openMVG::D2R(deg);
if (!openMVG::is_finite(rad)) { FUZZ_BAIL(); }
// Validation: computes conversion and ensures finiteness.

// Radians to degrees conversion
double r = *FUZZ_PARAM(double);
volatile double d = openMVG::R2D(r);
if (!openMVG::is_finite(d)) { FUZZ_BAIL(); }
// Validation: computes conversion and ensures finiteness.

// Build a valid rotation matrix via Z*Y*X Euler composition
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 2862933555777941757ULL + 3037000493ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
double ax = drand() * 6.283185307179586; // [-approx,approx) range via scaling
double ay = drand() * 6.283185307179586;
double az = drand() * 6.283185307179586;
openMVG::Mat3 Rx = openMVG::RotationAroundX(ax);
openMVG::Mat3 Ry = openMVG::RotationAroundY(ay);
openMVG::Mat3 Rz = openMVG::RotationAroundZ(az);
openMVG::Mat3 R = Rz * Ry * Rx;
double mag = openMVG::getRotationMagnitude(R);
// Property: magnitude should be finite and >= 0
if (!(openMVG::is_finite(mag) && mag >= 0.0)) { FUZZ_BAIL(); }
// Validation: constructs a guaranteed rotation matrix and checks basic properties.

double x = *FUZZ_PARAM(double);
double s = openMVG::SIGN(x);
// Contract: return 1.0 if x >= 0 else -1.0
if (!((x >= 0.0 && s == 1.0) || (x < 0.0 && s == -1.0))) { FUZZ_BAIL(); }
// Validation: enforces function's stated behavior.

// Build a random-sized vector (size 1..16) using an internal PRNG
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 11400714819323198485ULL + 0x9E3779B97F4A7C15ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int n = (unsigned int)((urand() % 16ULL) + 1ULL);
openMVG::Vec v(n);
for (unsigned int i = 0; i < n; ++i) v[i] = drand();
double norm_inf = openMVG::NormLInfinity(v);
// Must be >= 0 and finite
if (!(openMVG::is_finite(norm_inf) && norm_inf >= 0.0)) { FUZZ_BAIL(); }
// Validation: builds vector input; verifies non-negativity and finiteness.

// Two vectors of same size (1..16), values via PRNG
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 3202034522624059733ULL + 1ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int n = (unsigned int)((urand() % 16ULL) + 1ULL);
openMVG::Vec x(n), y(n);
for (unsigned int i = 0; i < n; ++i) { x[i] = drand(); y[i] = drand(); }
double d = openMVG::DistanceLInfinity(x, y);
if (!(openMVG::is_finite(d) && d >= 0.0)) { FUZZ_BAIL(); }
// Validation: enforces same-size vectors and checks metric non-negativity.

// Generate center and up; avoid degenerate/collinear cases using PRNG
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 6364136223846793005ULL + 1442695040888963407ULL; return seed; };
auto drand = [&](){ double u = (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); return 2.0*u - 1.0; };
openMVG::Vec3 center(drand(), drand(), drand());
openMVG::Vec3 up(drand(), drand(), drand());
// Enforce: center != 0
if (center.norm() < 1e-12) { FUZZ_BAIL(); }
// Enforce: up not near zero
if (up.norm() < 1e-12) { up = openMVG::Vec3::UnitY(); }
// Enforce: up not collinear with center
openMVG::Vec3 cN = center.normalized();
double col = std::abs(cN.dot(up.normalized()));
if (col > 0.999) { // perturb up slightly
    up = (up + openMVG::Vec3(1e-3, -2e-3, 3e-3)).normalized();
    col = std::abs(cN.dot(up));
    if (col > 0.999) { FUZZ_BAIL(); }
}
openMVG::Mat3 R = openMVG::LookAt(center, up);
// Soft check: R should be roughly orthonormal
if (!((R * R.transpose() - openMVG::Mat3::Identity()).norm() < 1e-4)) { /* tolerate */ }
// Validation: enforces non-degenerate inputs; constructs and softly validates rotation.

// Generate eye, center, up; avoid degenerate/collinear cases using PRNG
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 1442695040888963407ULL + 6364136223846793005ULL; return seed; };
auto drand = [&](){ double u = (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); return 2.0*u - 1.0; };
openMVG::Vec3 eye(drand(), drand(), drand());
openMVG::Vec3 center(drand(), drand(), drand());
openMVG::Vec3 up(drand(), drand(), drand());
openMVG::Vec3 dir = center - eye;
if (dir.norm() < 1e-12) { FUZZ_BAIL(); }
if (up.norm() < 1e-12) { up = openMVG::Vec3::UnitY(); }
double col = std::abs(dir.normalized().dot(up.normalized()));
if (col > 0.999) { up = (up + openMVG::Vec3(1e-3, -2e-3, 3e-3)).normalized(); col = std::abs(dir.normalized().dot(up)); if (col > 0.999) { FUZZ_BAIL(); } }
openMVG::Mat3 R = openMVG::LookAt2(eye, center, up);
if (!((R * R.transpose() - openMVG::Mat3::Identity()).norm() < 1e-4)) { /* tolerate */ }
// Validation: enforces valid direction and non-collinearity; softly validates rotation.

// Horizontally concat two matrices with same number of rows using PRNG
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 3935559000370003845ULL + 2691343689449507681ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int rows = (unsigned int)((urand() % 4ULL) + 1ULL); // 1..4
unsigned int c1   = (unsigned int)((urand() % 4ULL) + 1ULL); // 1..4
unsigned int c2   = (unsigned int)((urand() % 4ULL) + 1ULL); // 1..4
openMVG::Mat A(rows, c1), B(rows, c2);
for (unsigned int r = 0; r < rows; ++r) { for (unsigned int c = 0; c < c1; ++c) A(r,c) = drand(); }
for (unsigned int r = 0; r < rows; ++r) { for (unsigned int c = 0; c < c2; ++c) B(r,c) = drand(); }
auto C = openMVG::HStack(A, B);
// Post-condition: C has rows and c1+c2 columns
if (!(C.rows() == (int)rows && C.cols() == (int)(c1 + c2))) { FUZZ_BAIL(); }
// Validation: enforces row equality and checks resulting shape.

// Vertically concat two matrices with same number of columns using PRNG
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 3202034522624059733ULL + 3935559000370003845ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int cols = (unsigned int)((urand() % 4ULL) + 1ULL); // 1..4
unsigned int r1   = (unsigned int)((urand() % 4ULL) + 1ULL); // 1..4
unsigned int r2   = (unsigned int)((urand() % 4ULL) + 1ULL); // 1..4
openMVG::Mat A(r1, cols), B(r2, cols);
for (unsigned int r = 0; r < r1; ++r) { for (unsigned int c = 0; c < cols; ++c) A(r,c) = drand(); }
for (unsigned int r = 0; r < r2; ++r) { for (unsigned int c = 0; c < cols; ++c) B(r,c) = drand(); }
auto C = openMVG::VStack(A, B);
if (!(C.cols() == (int)cols && C.rows() == (int)(r1 + r2))) { FUZZ_BAIL(); }
// Validation: enforces column equality and checks resulting shape.

// Build a small random matrix and compute its Frobenius norm (sizes <= 8x8)
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 11400714819323198485ULL + 7046029254386353131ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int rows = (unsigned int)((urand() % 8ULL) + 1ULL);
unsigned int cols = (unsigned int)((urand() % 8ULL) + 1ULL);
openMVG::Mat A(rows, cols);
for (unsigned int r = 0; r < rows; ++r) for (unsigned int c = 0; c < cols; ++c) A(r,c) = drand();
double fn = openMVG::FrobeniusNorm(A);
if (!(openMVG::is_finite(fn) && fn >= 0.0)) { FUZZ_BAIL(); }
// Validation: verifies non-negativity and finiteness of norm.

// Two matrices of same shape
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 2862933555777941757ULL + 3037000493ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int rows = (unsigned int)((urand() % 8ULL) + 1ULL);
unsigned int cols = (unsigned int)((urand() % 8ULL) + 1ULL);
openMVG::Mat A(rows, cols), B(rows, cols);
for (unsigned int r = 0; r < rows; ++r) for (unsigned int c = 0; c < cols; ++c) { A(r,c) = drand(); B(r,c) = drand(); }
double fd = openMVG::FrobeniusDistance(A, B);
if (!(openMVG::is_finite(fd) && fd >= 0.0)) { FUZZ_BAIL(); }
// Validation: ensures same shape and checks metric non-negativity.

// Same-shape matrices with non-zero Frobenius norms
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 3202034522624059733ULL + 1ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int rows = (unsigned int)((urand() % 8ULL) + 1ULL);
unsigned int cols = (unsigned int)((urand() % 8ULL) + 1ULL);
openMVG::Mat A(rows, cols), B(rows, cols);
for (unsigned int r = 0; r < rows; ++r) for (unsigned int c = 0; c < cols; ++c) { A(r,c) = drand(); B(r,c) = drand(); }
double na = A.norm(); double nb = B.norm();
if (na == 0.0 || nb == 0.0) { FUZZ_BAIL(); }
double cosv = openMVG::CosinusBetweenMatrices(A, B);
// Cosine similarity is within [-1, 1]
if (!(openMVG::is_finite(cosv) && cosv >= -1.0 - 1e-9 && cosv <= 1.0 + 1e-9)) { FUZZ_BAIL(); }
// Validation: avoids division by zero and checks cosine bounds.

// Build a matrix and compute per-row mean and variance
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 11400714819323198485ULL + 14029467366897019727ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int rows = (unsigned int)((urand() % 8ULL) + 1ULL);
unsigned int cols = (unsigned int)((urand() % 8ULL) + 1ULL);
openMVG::Mat A(rows, cols);
for (unsigned int r = 0; r < rows; ++r) for (unsigned int c = 0; c < cols; ++c) A(r,c) = drand();
openMVG::Vec mean, var;
openMVG::MeanAndVarianceAlongRows(A, &mean, &var);
// Contract: output vectors sized to A.rows()
if (!(mean.size() == (int)rows && var.size() == (int)rows)) { FUZZ_BAIL(); }
// Validation: supplies non-null pointers and checks output sizes.

// Create a small matrix (sizes <= 8x8) with deterministic PRNG values
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 3935559000370003845ULL + 2691343689449507681ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
unsigned int rows = (unsigned int)((urand() % 8ULL) + 1ULL);
unsigned int cols = (unsigned int)((urand() % 8ULL) + 1ULL);
openMVG::Mat mat(rows, cols);
for (unsigned int r = 0; r < rows; ++r) {
  for (unsigned int c = 0; c < cols; ++c) {
    mat(r, c) = drand();
  }
}
// Obtain a writable random filename from the fuzzer runtime
const char *filename = FUZZ_PARAM_FILENAME();
// Optional prefix: keep it short to limit file size
std::string prefix = FUZZ_PARAM_STR();
if (prefix.size() > 8) prefix.resize(8);
// Invoke export; the runtime should provide a writable path
bool ok = openMVG::exportMatToTextFile(mat, filename, prefix);
// Do not treat IO failure as API misuse; filesystem conditions may vary. Best-effort call only.
volatile bool sink = ok; (void)sink;
// Validation: builds a valid matrix, uses a fuzzer-provided writable filename, and calls the exporter without enforcing success.

// Exercise is_finite with a random value and a guaranteed-finite value
double v = *FUZZ_PARAM(double);
int rv = openMVG::is_finite(v);
volatile int sink1 = rv; (void)sink1;
// Also verify contract on a known finite constant
double w = 1.2345;
int rw = openMVG::is_finite(w);
if (!(rw != 0)) { FUZZ_BAIL(); }
// Validation: calls is_finite on arbitrary input and asserts it returns non-zero for a known finite value.

// Instantiate template with Type=double over a std::vector<double>
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 11400714819323198485ULL + 7046029254386353131ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
std::vector<double> data;
unsigned int n = (unsigned int)(urand() % 33ULL); // 0..32 elements
for (unsigned int i = 0; i < n; ++i) data.push_back(drand());
double mn = 0.0, mx = 0.0, mean = 0.0, med = 0.0;
bool ok = openMVG::minMaxMeanMedian<double>(data.begin(), data.end(), mn, mx, mean, med);
if (!ok) {
  // Range may be empty; this is allowed. No postconditions to enforce.
} else {
  // For non-empty ranges: min <= median <= max and mean within [min, max]
  if (!(mn <= med && med <= mx)) { FUZZ_BAIL(); }
  if (!(mn <= mean && mean <= mx)) { FUZZ_BAIL(); }
}
volatile bool sink = ok; (void)sink;
// Validation: covers both empty and non-empty ranges; enforces basic order/mean properties when non-empty.

// Instantiate template with T=double and validate append/count/monotonicity
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto urand = [&](){ seed = seed * 2862933555777941757ULL + 3037000493ULL; return seed; };
auto drand = [&](){ return (double)((long long)(urand() >> 11)) / (double)(1ULL << 53); };
// Range endpoints; enforce start < end to avoid degenerate interval
double a = drand();
double b = drand();
if (a == b) { b = a + 1.0; }
double start = std::min(a, b);
double end   = std::max(a, b);
// Positive number of splits
int nb_split = (int)((urand() % 32ULL) + 1ULL); // 1..32
// Pre-populate output vector to exercise append behavior
std::vector<double> d_range;
unsigned int prefill = (unsigned int)(urand() % 3ULL);
for (unsigned int i = 0; i < prefill; ++i) d_range.push_back(drand());
size_t old_sz = d_range.size();
openMVG::SplitRange<double>(start, end, nb_split, d_range);
// Determine how many endpoints should have been appended
size_t expected_added = ((end - start) < (double)nb_split) ? 2u : (size_t)(nb_split + 1);
if (!(d_range.size() == old_sz + expected_added)) { FUZZ_BAIL(); }
// Validate endpoints of the appended segment
size_t base = old_sz;
// Tolerate tiny FP error
auto approx_eq = [](double x, double y){ return std::abs(x - y) <= 1e-9 * (1.0 + std::abs(x) + std::abs(y)); };
if (!approx_eq(d_range[base + 0], start)) { FUZZ_BAIL(); }
if (!approx_eq(d_range.back(), end)) { FUZZ_BAIL(); }
// Monotonic non-decreasing within appended segment
for (size_t i = base + 1; i < d_range.size(); ++i) {
  if (d_range[i] + 1e-12 < d_range[i - 1]) { FUZZ_BAIL(); }
}
// Validation: enforces positive split count, ordered endpoints, correct append count, endpoint equality, and monotonicity of the produced partition.

// Choose a concrete pixel type T for this Image<T>. We branch at runtime and instantiate at compile-time.
// Track type and geometry via attributes on the opaque pointer.
int tsel = (int)(*FUZZ_PARAM(unsigned int) % 4); // 0:u8, 1:int, 2:float, 3:double
void *img = nullptr;
if (tsel == 0) {
    // T = uint8_t
    auto *p = new openMVG::image::Image<uint8_t>();
    img = (void*)p;
    FUZZ_SET_ATTR_INT(img, "img_t", 0);
    FUZZ_SET_ATTR_INT(img, "width", p->Width());   // expected 0
    FUZZ_SET_ATTR_INT(img, "height", p->Height()); // expected 0
} else if (tsel == 1) {
    auto *p = new openMVG::image::Image<int>();
    img = (void*)p;
    FUZZ_SET_ATTR_INT(img, "img_t", 1);
    FUZZ_SET_ATTR_INT(img, "width", p->Width());
    FUZZ_SET_ATTR_INT(img, "height", p->Height());
} else if (tsel == 2) {
    auto *p = new openMVG::image::Image<float>();
    img = (void*)p;
    FUZZ_SET_ATTR_INT(img, "img_t", 2);
    FUZZ_SET_ATTR_INT(img, "width", p->Width());
    FUZZ_SET_ATTR_INT(img, "height", p->Height());
} else {
    auto *p = new openMVG::image::Image<double>();
    img = (void*)p;
    FUZZ_SET_ATTR_INT(img, "img_t", 3);
    FUZZ_SET_ATTR_INT(img, "width", p->Width());
    FUZZ_SET_ATTR_INT(img, "height", p->Height());
}
// The default constructor creates a 0x0 image; accessing pixels before resize is invalid.
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(img, "width") == 0 && FUZZ_GET_ATTR_INT(img, "height") == 0, "Default Image must be 0x0");

// Assign from a row-major Eigen matrix of the same pixel type.
int tsel = FUZZ_GET_ATTR_INT(img, "img_t");
// Choose small dimensions to keep allocations cheap.
int w = (int)(*FUZZ_PARAM(unsigned int) % 64) + 1; // [1,64]
int h = (int)(*FUZZ_PARAM(unsigned int) % 64) + 1; // [1,64]
if (tsel == 0) {
    using T = uint8_t;
    Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor> M(h, w);
    // Fill with random-ish data using setRandom; cast to T to remain in-range.
    M = Eigen::Matrix<int, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor>::Random(h, w).unaryExpr([](int v){ return static_cast<T>(v); });
    auto *p = static_cast<openMVG::image::Image<T>*>(img);
    *p = M; // invokes operator=
    FUZZ_SET_ATTR_INT(img, "width", p->Width());
    FUZZ_SET_ATTR_INT(img, "height", p->Height());
    FUZZ_ASSERT(p->Width() == w && p->Height() == h, "Assignment must resize image to matrix dimensions");
} else if (tsel == 1) {
    using T = int;
    Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor> M(h, w);
    M.setRandom();
    auto *p = static_cast<openMVG::image::Image<T>*>(img);
    *p = M;
    FUZZ_SET_ATTR_INT(img, "width", p->Width());
    FUZZ_SET_ATTR_INT(img, "height", p->Height());
    FUZZ_ASSERT(p->Width() == w && p->Height() == h, "Assignment must resize image to matrix dimensions");
} else if (tsel == 2) {
    using T = float;
    Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor> M(h, w);
    M.setRandom();
    auto *p = static_cast<openMVG::image::Image<T>*>(img);
    *p = M;
    FUZZ_SET_ATTR_INT(img, "width", p->Width());
    FUZZ_SET_ATTR_INT(img, "height", p->Height());
    FUZZ_ASSERT(p->Width() == w && p->Height() == h, "Assignment must resize image to matrix dimensions");
} else if (tsel == 3) {
    using T = double;
